# Program 2: Factorial using recursion
def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

num = int(input("Enter a number: "))
print(factorial(num))

# Program 3: Count even and odd numbers in a list
def count_even_odd(numbers):
    even = 0
    odd = 0
    for x in numbers:
        if x % 2 == 0:
            even += 1
        else:
            odd += 1
    return even, odd

e, o = count_even_odd([1, 2, 3, 4, 5, 6])
print(f"even={e}, odd={o}")

# Program 4: Sum of first N natural numbers using recursion
def rec_sum(n):
    if n == 0:
        return 0
    return n + rec_sum(n - 1)

print(rec_sum(5))

# Program 4: Maximum of many numbers using *args
def maximum(*numbers):
    big = numbers[0]
    for x in numbers:
        if x > big:
            big = x
    return big

print(maximum(10, 5, 8, 12, 3))

# Program 3: Safe division (return 0 if denominator is 0)
def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return 0

print(safe_divide(10, 2))
print(safe_divide(10, 0))

