# Program 3: Calculator handling several exceptions
def calculate(a, b, op):
    try:
        if op == "+":
            return a + b
        elif op == "/":
            return a / b
    except ZeroDivisionError:
        return "Cannot divide by zero"
    except TypeError:
        return "Invalid operand type"

print(calculate(10, 0, "/"))
print(calculate("a", 5, "+"))

# Program 4: Define and raise a custom exception
class NegativeNumberError(Exception):
    pass

def check(value):
    if value < 0:
        raise NegativeNumberError("Value cannot be negative")
    return value

try:
    print("Valid:", check(25))
    print("Valid:", check(-7))
except NegativeNumberError as e:
    print("NegativeNumberError:", e)

# Assignment 1: Nth Fibonacci number (recursive)
def fib(n):
    if n <= 2:
        return 1
    return fib(n - 1) + fib(n - 2)

print(fib(6))

# Assignment 2: GCD of two numbers (recursive)
def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

print(gcd(12, 18))

